{
    size_t i;
    int power_limited = 0, slew_limited = 0;
    double requested_torque[4];
    double scaled_torque[4];
    double power[4];
    double motoring_sum = 0.0, regen_sum = 0.0;
    double motoring_scale, regen_scale;
    double axis_norm;
    adcs_vec3_t axis_unit, axis_term, sum_term;
    adcs_vec3_t requested_body_torque = {0, 0, 0}, delivered_body_torque = {0, 0, 0};
    adcs_vec3_t momentum_nms = {0, 0, 0};
    double requested_net, delivered_motoring, delivered_regen, delivered_net;
    double filtered_abs_power;
    int config_valid, any_limit;
    adcs_status_t st;

    config_valid = isfinite(wp_config.trip_filtered_w) && isfinite(wp_config.release_filtered_w) &&
                   isfinite(wp_config.filter_alpha) && isfinite(wp_config.motoring_limit_w) &&
                   isfinite(wp_config.regenerative_limit_w) &&
                   isfinite(wp_config.max_torque_slew_nm_per_cycle) &&
                   (wp_config.release_filtered_w >= 0.0) &&
                   (wp_config.release_filtered_w < wp_config.trip_filtered_w) &&
                   (wp_config.filter_alpha >= 0.0) && (wp_config.filter_alpha <= 1.0) &&
                   (wp_config.motoring_limit_w > 0.0) && (wp_config.regenerative_limit_w > 0.0) &&
                   (wp_config.max_torque_slew_nm_per_cycle > 0.0) &&
                   (wp_config.release_cycles >= 1U) && (wp_config.release_cycles <= 20U);

    if ((wp_input.wheels == NULL) || (wp_input.torque_nm == NULL) || (wp_input.wheel_count != 4U) ||
        (!config_valid)) {
        wp_state.mode = WP_FAULT;
        wp_state.clean = 0U;
        wp_state.filtered_abs_power_w = 0.0;
        for (i = 0; i < 4U; i++) {
            wp_state.previous_torque_nm[i] = 0.0;
            wp_output.limited_torque_nm[i] = 0.0;
        }
        wp_output.mode = WP_FAULT;
        wp_output.clean = 0U;
        wp_output.power_limited_mask = 0U;
        wp_output.slew_limited_mask = 0U;
        wp_output.requested_net_power_w = 0.0;
        wp_output.delivered_net_power_w = 0.0;
        wp_output.requested_motoring_power_w = 0.0;
        wp_output.requested_regenerative_power_w = 0.0;
        wp_output.delivered_motoring_power_w = 0.0;
        wp_output.delivered_regenerative_power_w = 0.0;
        wp_output.filtered_abs_power_w = 0.0;
        wp_output.momentum_norm_nms = 0.0;
        wp_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
        wp_output.requested_body_torque_nm = (adcs_vec3_t){0, 0, 0};
        wp_output.delivered_body_torque_nm = (adcs_vec3_t){0, 0, 0};
        return;
    }

    if (!wp_input.enable) {
        wp_state.mode = WP_NORMAL;
        wp_state.clean = 0U;
        wp_state.filtered_abs_power_w = 0.0;
        for (i = 0; i < 4U; i++) {
            wp_state.previous_torque_nm[i] = 0.0;
            wp_output.limited_torque_nm[i] = 0.0;
        }
        wp_output.mode = WP_NORMAL;
        wp_output.clean = 0U;
        wp_output.power_limited_mask = 0U;
        wp_output.slew_limited_mask = 0U;
        wp_output.requested_net_power_w = 0.0;
        wp_output.delivered_net_power_w = 0.0;
        wp_output.requested_motoring_power_w = 0.0;
        wp_output.requested_regenerative_power_w = 0.0;
        wp_output.delivered_motoring_power_w = 0.0;
        wp_output.delivered_regenerative_power_w = 0.0;
        wp_output.filtered_abs_power_w = 0.0;
        wp_output.momentum_norm_nms = 0.0;
        wp_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
        wp_output.requested_body_torque_nm = (adcs_vec3_t){0, 0, 0};
        wp_output.delivered_body_torque_nm = (adcs_vec3_t){0, 0, 0};
        return;
    }

    st = adcs_wheel_momentum(wp_input.wheels, wp_input.wheel_count, &momentum_nms);
    for (i = 0; i < 4U; i++) {
        if ((!isfinite(wp_input.torque_nm[i])) || (!isfinite(wp_input.wheels[i].speed_rad_s)) ||
            (!isfinite(wp_input.wheels[i].inertia_kg_m2))) {
            st = ADCS_E_RANGE;
            break;
        }
    }
    if (st != ADCS_OK) {
        wp_state.mode = WP_FAULT;
        wp_state.clean = 0U;
        wp_state.filtered_abs_power_w = 0.0;
        for (i = 0; i < 4U; i++) {
            wp_state.previous_torque_nm[i] = 0.0;
            wp_output.limited_torque_nm[i] = 0.0;
        }
        wp_output.mode = WP_FAULT;
        wp_output.clean = 0U;
        wp_output.power_limited_mask = 0U;
        wp_output.slew_limited_mask = 0U;
        wp_output.requested_net_power_w = 0.0;
        wp_output.delivered_net_power_w = 0.0;
        wp_output.requested_motoring_power_w = 0.0;
        wp_output.requested_regenerative_power_w = 0.0;
        wp_output.delivered_motoring_power_w = 0.0;
        wp_output.delivered_regenerative_power_w = 0.0;
        wp_output.filtered_abs_power_w = 0.0;
        wp_output.momentum_norm_nms = 0.0;
        wp_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
        wp_output.requested_body_torque_nm = (adcs_vec3_t){0, 0, 0};
        wp_output.delivered_body_torque_nm = (adcs_vec3_t){0, 0, 0};
        return;
    }
    wp_output.momentum_nms = momentum_nms;
    wp_output.momentum_norm_nms = adcs_vec3_norm(&momentum_nms);

    for (i = 0; i < 4U; i++) {
        requested_torque[i] = wp_input.torque_nm[i];
        power[i] = requested_torque[i] * wp_input.wheels[i].speed_rad_s;
        if (power[i] >= 0.0)
            motoring_sum += power[i];
        else
            regen_sum += -power[i];
    }
    requested_net = motoring_sum - regen_sum;
    wp_output.requested_motoring_power_w = motoring_sum;
    wp_output.requested_regenerative_power_w = regen_sum;
    wp_output.requested_net_power_w = requested_net;

    for (i = 0; i < 4U; i++) {
        axis_unit = wp_input.wheels[i].axis_body;
        axis_norm = adcs_vec3_norm(&axis_unit);
        if (axis_norm > ADCS_EPS_NORM) {
            axis_unit = adcs_vec3_scale(&axis_unit, 1.0 / axis_norm);
            axis_term = adcs_vec3_scale(&axis_unit, requested_torque[i]);
            sum_term = adcs_vec3_add(&requested_body_torque, &axis_term);
            requested_body_torque = sum_term;
        }
    }
    wp_output.requested_body_torque_nm = adcs_vec3_scale(&requested_body_torque, -1.0);

    motoring_scale = (motoring_sum > wp_config.motoring_limit_w && motoring_sum > 0.0)
                         ? (wp_config.motoring_limit_w / motoring_sum)
                         : 1.0;
    regen_scale = (regen_sum > wp_config.regenerative_limit_w && regen_sum > 0.0)
                      ? (wp_config.regenerative_limit_w / regen_sum)
                      : 1.0;

    for (i = 0; i < 4U; i++) {
        if (power[i] >= 0.0)
            scaled_torque[i] = requested_torque[i] * motoring_scale;
        else
            scaled_torque[i] = requested_torque[i] * regen_scale;
    }
    for (i = 0; i < 4U; i++) {
        if (scaled_torque[i] != requested_torque[i])
            power_limited = 1;
    }

    for (i = 0; i < 4U; i++) {
        double delta = scaled_torque[i] - wp_state.previous_torque_nm[i];
        double limited;
        if (delta > wp_config.max_torque_slew_nm_per_cycle) {
            limited = wp_state.previous_torque_nm[i] + wp_config.max_torque_slew_nm_per_cycle;
            slew_limited = 1;
        } else if (delta < -wp_config.max_torque_slew_nm_per_cycle) {
            limited = wp_state.previous_torque_nm[i] - wp_config.max_torque_slew_nm_per_cycle;
            slew_limited = 1;
        } else {
            limited = scaled_torque[i];
        }
        wp_output.limited_torque_nm[i] = limited;
    }

    delivered_motoring = 0.0;
    delivered_regen = 0.0;
    for (i = 0; i < 4U; i++) {
        double p = wp_output.limited_torque_nm[i] * wp_input.wheels[i].speed_rad_s;
        if (p >= 0.0)
            delivered_motoring += p;
        else
            delivered_regen += -p;
    }
    delivered_net = delivered_motoring - delivered_regen;
    wp_output.delivered_motoring_power_w = delivered_motoring;
    wp_output.delivered_regenerative_power_w = delivered_regen;
    wp_output.delivered_net_power_w = delivered_net;

    for (i = 0; i < 4U; i++) {
        axis_unit = wp_input.wheels[i].axis_body;
        axis_norm = adcs_vec3_norm(&axis_unit);
        if (axis_norm > ADCS_EPS_NORM) {
            axis_unit = adcs_vec3_scale(&axis_unit, 1.0 / axis_norm);
            axis_term = adcs_vec3_scale(&axis_unit, wp_output.limited_torque_nm[i]);
            sum_term = adcs_vec3_add(&delivered_body_torque, &axis_term);
            delivered_body_torque = sum_term;
        }
    }
    wp_output.delivered_body_torque_nm = adcs_vec3_scale(&delivered_body_torque, -1.0);

    filtered_abs_power = wp_config.filter_alpha * fabs(requested_net) +
                         (1.0 - wp_config.filter_alpha) * wp_state.filtered_abs_power_w;
    wp_state.filtered_abs_power_w = filtered_abs_power;
    wp_output.filtered_abs_power_w = filtered_abs_power;

    any_limit = power_limited || slew_limited || (filtered_abs_power >= wp_config.trip_filtered_w);

    if (any_limit) {
        wp_state.mode = WP_LIMITED;
        wp_state.clean = 0U;
    } else if (wp_state.mode == WP_LIMITED) {
        if (filtered_abs_power <= wp_config.release_filtered_w) {
            wp_state.mode = WP_RECOVERING;
            wp_state.clean = 1U;
        } else {
            wp_state.mode = WP_LIMITED;
            wp_state.clean = 0U;
        }
    } else if (wp_state.mode == WP_RECOVERING) {
        if (filtered_abs_power <= wp_config.release_filtered_w) {
            wp_state.clean += 1U;
            if (wp_state.clean >= wp_config.release_cycles) {
                wp_state.mode = WP_NORMAL;
                wp_state.clean = 0U;
            }
        } else {
            wp_state.mode = WP_LIMITED;
            wp_state.clean = 0U;
        }
    } else {
        wp_state.mode = WP_NORMAL;
        wp_state.clean = 0U;
    }

    wp_output.power_limited_mask = 0U;
    wp_output.slew_limited_mask = 0U;
    for (i = 0; i < 4U; i++) {
        wp_state.previous_torque_nm[i] = wp_output.limited_torque_nm[i];
    }
    for (i = 0; i < 4U; i++) {
        if (fabs(scaled_torque[i] - requested_torque[i]) > 0.0)
            wp_output.power_limited_mask |= (unint32)(1U << i);
    }
    for (i = 0; i < 4U; i++) {
        if (fabs(wp_output.limited_torque_nm[i] - scaled_torque[i]) > 0.0)
            wp_output.slew_limited_mask |= (unint32)(1U << i);
    }
    wp_output.mode = wp_state.mode;
    wp_output.clean = wp_state.clean;
}

